from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, Preformatted
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from pypdf import PdfReader
R=Path(__file__).resolve().parents[1]
S=getSampleStyleSheet()
for name,size,lead,font,col in [('BodyN',10,16,'Helvetica','#394235'),('HeadN',20,26,'Helvetica-Bold','#3d553c'),('TitleN',42,47,'Times-Roman','#344d34'),('SmallN',8.5,12,'Helvetica','#687361'),('CodeN',9,14,'Courier','#344d34')]:
 S.add(ParagraphStyle(name=name,fontName=font,fontSize=size,leading=lead,textColor=colors.HexColor(col),spaceAfter=12,keepWithNext=name=='HeadN'))
def p(t,style='BodyN'):return Paragraph(escape(t).replace('&lt;br/&gt;','<br/>'),S[style])
def h(t):return p(t,'HeadN')
def box(t):
 t=Table([[p(t)]],colWidths=[495]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#eaf0e3')),('BOX',(0,0),(-1,-1),.5,colors.HexColor('#c2ceb6')),('LEFTPADDING',(0,0),(-1,-1),16),('RIGHTPADDING',(0,0),(-1,-1),16),('TOPPADDING',(0,0),(-1,-1),16),('BOTTOMPADDING',(0,0),(-1,-1),8)]));return t
story=[]
def add(*items):story.extend(items)
def page():add(PageBreak())
add(p('OPTITAC / PROJECT NOVELTY','SmallN'),Spacer(1,32),p('Optimization<br/>Autopsy','TitleN'),p('An error-aware counterfactual notebook for compiler optimization','HeadN'),Spacer(1,14),box('Core idea: make each optimization inspectable as an experiment. Show what changed, whether the observed behavior survived, and what happens when that pass is removed.'),Spacer(1,24),h('What is the proposed novelty?'),p('OptiTAC combines pass-by-pass replay, runtime-error preservation, leave-one-pass-out experiments and a portable evidence record in a source-to-TAC learning workbench. The proposed contribution is this integrated investigation workflow and its potential educational value.'),p('A conventional before/after display shows the final transformation. OptiTAC also lets a user examine intermediate checkpoints, locate the earliest observed divergence, and compare a pipeline against versions with individual passes omitted.'),p('The five optimization algorithms themselves are established techniques. This document does not claim that pass debugging, translation validation, omission experiments or fault injection were invented by OptiTAC. Global uniqueness and publication novelty require a wider comparison and empirical evaluation.','SmallN'))
page()
add(p('01 / HOW IT WORKS','SmallN'),h('Five parts of one investigation'),p('1. Transformation replay. After every selected pass, the engine stores independent before/after TAC snapshots, instruction IDs, rewrite explanations and the pass round. Even a pass with no rewrite remains visible.'),p('2. Error-aware observation. The original and transformed TAC are executed with the same interpreter. Successful return values are compared with Object.is; failed executions are compared by their error messages. A preserved error is labelled as an error, not as successful execution.'),p('3. First-divergence localization. Each checkpoint is compared with the original observation. The earliest unequal checkpoint is retained, even if a later transformation masks the difference. This identifies a recorded divergence, not a minimal root cause or formal causal proof.'),p('4. Counterfactual omission. The entire selected pipeline is rerun once per enabled pass, with that pass removed. The workbench reports final TAC count, count difference and preservation of the original observation.'),p('5. Exportable evidence. JSON contains source, selections, tokens, AST, TAC, checkpoints, logs and execution observations. A labelled return-value fault can be injected after optimization to demonstrate detection. It is excluded from omission comparisons.'),box('The distinctive experience is the connection: inspect a rewrite, inspect its semantic observation, then challenge its contribution by removing the pass.'),Spacer(1,16),p('Implementation: src/compiler/lab.ts orchestrates the experiment; src/App.tsx exposes Autopsy, Counterfactual and Structure views. Selected passes run in a fixed order until unchanged or ten rounds. A run records at most 50 ordinary checkpoints plus one optional injected-fault checkpoint.','SmallN'))
page()
add(p('02 / EXAMPLES THAT MAKE THE IDEA CONCRETE','SmallN'),h('Optimization is more than shorter code'),p('Example A - A propagation cascade'),Preformatted('int a = 10;\nint b = a + 5;\nint spare = 99;\nint c = b * 2;\nreturn c;',S['CodeN']),p('With all passes enabled, this example reduces from seven TAC instructions to return 30. Replay shows the intermediate substitutions and folds. Omission experiments reveal what remains when a pass is unavailable; another pass may compensate across rounds.'),p('Example B - The unused computation that matters'),Preformatted('int a = 8;\nint unused = a / 0;\nreturn a;',S['CodeN']),p('The original execution fails with division by zero. Deleting the unused division would incorrectly change failure into return 8 under this interpreter. OptiTAC retains potentially trapping division and modulo operations, so the optimized program preserves the error.'),box('This example exposes the central teaching point: a value can be unused while its computation still has observable behavior.'),Spacer(1,14),p('Example C - A controlled wrong result'),p('For the cascade, the optional fault changes the return from 30 to 31 after normal optimization. Autopsy identifies the injected checkpoint as the first divergence. This is a deliberately seeded demonstration, not evidence of discovering a new compiler bug. On an erroring program, execution may never reach the modified return.'),p('These observations apply to the project interpreter. In particular, division-by-zero behavior here must not be generalized to C undefined behavior.','SmallN'))
page()
add(p('03 / POSITIONING AGAINST RELATED WORK','SmallN'),h('What is established, and what is proposed?'))
rows=[['Approach','Established capability','OptiTAC positioning'],['LLVM OptBisect [1]','Selectively disables optimizations to help locate errors.','Uses visible replay and full-pipeline omission experiments in a small teaching notebook.'],['LLVM remarks [2]','Reports information about optimization transformations.','Places rewrite explanations beside concrete outcomes and counterfactual instruction counts.'],['Alive2 [3,4]','Provides bounded translation validation for LLVM.','Checks concrete closed-program observations; does not match the strength of symbolic validation.']]
t=Table([[p(c,'SmallN') for c in row] for row in rows],colWidths=[105,190,200],repeatRows=1)
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dfe7d7')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#f3f4ee'),colors.white]),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),12),('BOTTOMPADDING',(0,0),(-1,-1),8),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9)]))
add(t,Spacer(1,20),h('A defensible novelty statement'),box('OptiTAC investigates an integrated error-aware counterfactual notebook for compiler education, linking pass-local rewrites, observed behavioral preservation and omission-based contribution analysis in a single inspectable workflow.'),Spacer(1,18),p('This is a candidate system and educational contribution. The comparison above establishes related foundations; it does not establish that no other tool combines them. A systematic survey of educational compilers and optimization-debugging interfaces is still needed.'),p('Instruction-count differences are not runtime speedups. Omission effects include interactions and are not additive. A zero difference can mean redundancy, compensation by another pass, or lack of applicability.','SmallN'))
page()
add(p('04 / EVIDENCE AND RESEARCH PATH','SmallN'),h('What the implementation supports'),p('Build and lint checks pass. Thirteen automated test cases cover the experiment pipeline, including a deterministic corpus of forty arithmetic programs, zero-division and zero-modulo traps, injected divergence, omission effects, snapshot isolation and numeric handling. Browser checks cover desktop/mobile behavior, error messages and JSON export. These are engineering checks, not a comparative research study.'),p('The language supports initialized int/float declarations, arithmetic, parentheses and returns. Arithmetic uses JavaScript Number, not fixed-width C integer semantics. There are no external runtime inputs; branching, loops, CFG analysis, symbolic verification, reduced counterexamples and persistent experiment history are not implemented.'),h('What would make a research claim convincing?'),p('Compare three interfaces: final before/after only; replay with outcomes; and the full replay-plus-omission workflow. Use a reproducible set of arithmetic programs, seeded transformation faults, numeric edge cases and observable-error cases. Measure fault detection, checkpoint-localization accuracy, explanation accuracy and time to complete investigation tasks.'),p('An appropriately designed learner study could test whether omission experiments improve understanding of pass interactions. Report participant selection, consent, task difficulty, uncertainty and failure cases. No participant data, measured learning benefit or publication acceptance currently exists.'),h('References'),p('[1] LLVM. Using -opt-bisect-limit to debug optimization errors. https://llvm.org/docs/OptBisect.html','SmallN'),p('[2] LLVM. Remarks. https://llvm.org/docs/Remarks.html','SmallN'),p('[3] AliveToolkit. Alive2 project documentation. https://github.com/AliveToolkit/alive2','SmallN'),p('[4] Lopes et al. Alive2: Bounded Translation Validation for LLVM. PLDI 2021. https://users.cs.utah.edu/~regehr/alive2-pldi21.pdf','SmallN'),p('Sources checked 13 October 2026. Project claims describe the inspected implementation.','SmallN'))
def footer(c,d):
 c.saveState();c.setStrokeColor(colors.HexColor('#ccd3c5'));c.line(44,43,551,43);c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#687361'));c.drawString(44,29,'OPTITAC / NOVELTY & TECHNICAL EXPLANATION');c.drawRightString(551,29,str(d.page));c.restoreState()
out=R/'output/pdf/OptiTAC-Novelty-Explained.pdf'
SimpleDocTemplate(str(out),pagesize=A4,leftMargin=44,rightMargin=44,topMargin=42,bottomMargin=59,title='OptiTAC - Novelty Explained',author='OptiTAC Project').build(story,onFirstPage=footer,onLaterPages=footer)
reader=PdfReader(out);text='\n'.join(pg.extract_text() for pg in reader.pages)
assert len(reader.pages)==5,len(reader.pages)
assert not any(s in text.lower() for s in ['review 2','75%','25%','assessment','completion percentage'])
print(f'Created {len(reader.pages)} pages: {out}')
